    [16985]={name="Windseeker Boots",quality=2,ilvl=25,sourceType="quest_reward",instructions="Reward from the quest 'New Life'. Pick it over the other reward choices.",zone="Stonetalon Mountains",questName="New Life",lore="As you have seen, though the land is in pain, the cycle of life is a powerful thing. Now we must do our part help it along. You must plant these seeds at the center of the destruction, to the west, in the Charred Vale."},
