    [22080]={name="Virtuous Crown",quality=4,ilvl=60,sourceType="quest_reward",instructions="Reward from the quest 'Saving the Best for Last'.",zone="Ironforge",questName="Saving the Best for Last",lore="That's an amazing story! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut."},
    [22149]={name="Beads of Ogre Mojo",quality=3,ilvl=63,sourceType="quest_reward",instructions="Reward from the quest 'Falrin's Vendetta'. Pick it over the other reward choices.",zone="Dire Maul",questName="Falrin's Vendetta",lore="Yet I'm not one to give out favors freely, even if you were sent here by an old friend. I hold nothing but hatred and contempt for our brutish ogre neighbors."},
    [22512]={name="Robe of Faith",quality=4,ilvl=92,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Robe of Faith'.",zone="Naxxramas",questName="Robe of Faith",lore="The poor souls whose last breaths were taken on the field of battle - stripped of everything including their dignity. Bring me the desecrated remnants of the departed along with reagents of purification and you shall know faith."},
